# OPA Rego 策略示例: 基于用户角色的数据访问控制
package istio.authz

default allow = false

allow {
    input.attributes.request.http.path = "/api/v1/financials"
    token.payload.role == "finance"
}

allow {
    input.attributes.request.http.path = "/api/v1/financials"
    token.payload.role == "auditor"
    startswith(input.attributes.request.http.method, "GET")
}
